#pragma once
static void checkExpansionCleanup(App& app,const std::string& dir){
 auto require=[](bool ok,const std::string& why){if(!ok)throw std::runtime_error("expand cleanup: "+why);};auto& s=app.s;Document d;d.setDefaultBondLength(30);std::vector<ObjectId> ring;double radius=30/(2*std::sin(3.141592653589793/5));for(int i=0;i<5;++i){ObjectId id;double a=-3.141592653589793/2+i*6.283185307179586/5;d.addAtom(Vec2(130+radius*std::cos(a),130+radius+radius*std::sin(a)),6,&id);ring.push_back(id);}for(int i=0;i<5;++i)d.addBond(ring[i],ring[(i+1)%5],nullptr);ObjectId ph,group;d.addAtom(Vec2(104,115),6,&ph);d.addAtom(Vec2(148,106),6,&group);require(nicknames::apply(d,ph,"Ph").ok()&&nicknames::apply(d,group,"COOH").ok(),"construct collapsed source");d.addBond(ring[0],ph,nullptr);d.addBond(ring[0],group,nullptr);
 s.cancel();s.doc=d;s.history.clear();s.selected={{ObjectKind::Atom,group}};s.input.bindDocument(s.doc.id());s.refresh();app.expandPending=false;auto before=s.doc.digest();auto formula=studio::analyze(s.doc,s.all()).plain;app.expandGroups();require(s.doc.stats().aliveAtoms==d.stats().aliveAtoms+2,"COOH expands its two oxygen atoms");require(app.status.find("自动整理")!=std::string::npos,"expansion reports automatic cleanup");
 for(auto id:ring)require(s.doc.atoms().alive(id)->position==d.atoms().alive(id)->position,"unselected ring stays fixed");require(s.doc.atoms().alive(ph)->position==d.atoms().alive(ph)->position&&s.doc.atomLabel(ph)=="Ph","unselected Ph stays collapsed and fixed");std::vector<ObjectId> atoms;for(auto ref:s.selected)if(ref.kind==ObjectKind::Atom)atoms.push_back(ref.id);studio_local_cleanup::Scope local;for(auto a:s.doc.atoms().records())if(a.isAlive())local.atoms.insert(a.id);local.movable.insert(atoms.begin(),atoms.end());auto q=studio_local_cleanup::quality(s.doc,local);require(q.crowd<1e-6,"expanded O and OH do not overlap the original skeleton");require(studio::analyze(s.doc,s.all()).plain==formula,"composition preserved");auto after=s.doc.digest();require(s.undo().ok()&&s.doc.digest()==before&&s.undo(true).ok()&&s.doc.digest()==after,"expansion plus cleanup is one undo and redo");s.selected.clear();s.fit();app.invalidate();app.screenshot(dir+"/expanded-cooh-cleaned.png");require(s.save(dir+"/expanded-cooh-cleaned.cdxml",true).ok(),"save cleaned expansion");
 std::ofstream(dir+"/expansion-cleanup-checks.json")<<"{\"automatic_after_expansion\":true,\"attached_cooh\":true,\"unselected_frame_fixed\":true,\"no_label_overlap\":true,\"formula_preserved\":true,\"one_undo_redo\":true}";
}
